<script setup lang="ts">
import {Edit,Refresh,Search} from '@element-plus/icons-vue';
import {computed,onMounted,ref,watch} from 'vue';
import {ElMessage,ElMessageBox} from 'element-plus';
import {ApiError} from '@/core/api/contracts';
import {enumLabel} from '@/core/i18n/enum-labels';
import {useAuthStore} from '@/core/auth/auth.store';
import {useRuntimeSettingsStore} from '@/core/settings/runtime-settings.store';
import DsDataTable from '@/design-system/components/DsDataTable.vue';
import DsEmpty from '@/design-system/components/DsEmpty.vue';
import DsListPageShell from '@/design-system/components/DsListPageShell.vue';
import DsPagination from '@/design-system/components/DsPagination.vue';
import DsTag from '@/design-system/components/DsTag.vue';
import {enterpriseMeteringApi,type MeteringQualityPage,type MeteringQualityRow} from '@/domain/iot/metering-loss';
import './enterprise-metering.css';

const runtime=useRuntimeSettingsStore(),auth=useAuthStore();
const loading=ref(true),saving=ref(false),dates=ref<[string,string]>(defaultRange()),status=ref(''),page=ref(1),pageSize=ref(runtime.pageSize);
const dialogVisible=ref(false),activeRow=ref<MeteringQualityRow>();
const correctionForm=ref({intervalEnergyId:0,correctionType:'MULTIPLIER',afterQuantity:0,reason:'',evidenceReference:''});
const result=ref<MeteringQualityPage>({total:0,page:1,pageSize:runtime.pageSize,goodCount:0,correctedCount:0,estimatedCount:0,issueCount:0,rows:[]});
function localDate(value:Date){return new Date(value.getTime()-value.getTimezoneOffset()*60000).toISOString().slice(0,10)}function defaultRange():[string,string]{const end=new Date(),start=new Date(end.getFullYear(),end.getMonth(),1);return[localDate(start),localDate(end)]}
function format(value:number){return Number(value||0).toLocaleString('zh-CN',{minimumFractionDigits:3,maximumFractionDigits:3})}
const correctionLabel:Record<string,string>={MULTIPLIER:'CT/PT 倍率',METER_REPLACEMENT:'换表衔接',ROLLOVER:'清零/翻转',DIRECTION:'正反向',TIME_ALIGNMENT:'时间对齐',MISSING_ESTIMATE:'缺失估算',DEDUPLICATION:'重复去重',OUTLIER:'异常突变'};
const canCorrect=computed(()=>auth.can('platform:enterprise-metering:quality:correct'));
const canApprove=computed(()=>auth.can('platform:enterprise-metering:quality:approve'));
const canShowCorrect=computed(()=>auth.canShow('platform:enterprise-metering:quality:correct'));
const canShowApprove=computed(()=>auth.canShow('platform:enterprise-metering:quality:approve'));
function tone(value:string){return value==='GOOD'?'success':value==='CORRECTED'?'primary':value==='MISSING'||value==='SUSPECT'?'error':'warning'}
function errorMessage(error:unknown,fallback:string){return error instanceof ApiError?error.message:fallback}
async function load(reset=false){if(reset)page.value=1;loading.value=true;try{result.value=await enterpriseMeteringApi.quality({periodStart:`${dates.value[0]}T00:00:00`,periodEnd:`${dates.value[1]}T23:59:59`,qualityStatus:status.value||undefined,page:page.value,pageSize:pageSize.value})}catch(error){ElMessage.error(errorMessage(error,'计量数据质量加载失败'))}finally{loading.value=false}}
function openCorrection(row:MeteringQualityRow){if(!auth.canEnter('platform:enterprise-metering:quality:correct'))return;if(!row.intervalEnergyId){ElMessage.warning('缺失记录需要先补录具有来源依据的区间电量，不能直接改成某个数字');return}activeRow.value=row;correctionForm.value={intervalEnergyId:row.intervalEnergyId,correctionType:'MULTIPLIER',afterQuantity:row.correctedQuantity,reason:'',evidenceReference:''};dialogVisible.value=true}
async function saveCorrection(){if(!canCorrect.value)return;if(correctionForm.value.afterQuantity===activeRow.value?.correctedQuantity||!correctionForm.value.reason.trim()||!correctionForm.value.evidenceReference.trim()){ElMessage.warning('修正值必须发生变化，并填写原因和证据');return}saving.value=true;try{await enterpriseMeteringApi.createReadingCorrection(correctionForm.value);dialogVisible.value=false;await load();ElMessage.success('计量修正已提交审批，原始值和当前结算值未被覆盖')}catch(error){ElMessage.error(errorMessage(error,'提交计量修正失败'))}finally{saving.value=false}}
async function reviewCorrection(row:MeteringQualityRow,decision:'APPROVED'|'REJECTED'){
  if(!row.correctionId||row.correctionVersion===undefined)return;
  try{let comment='已核验原始报文、表计事件与修正依据';if(decision==='APPROVED')await ElMessageBox.confirm('批准后会追加审计记录，并将修正值写入结算值；原始值永久保留。是否继续？','批准计量修正',{type:'warning',confirmButtonText:'批准',cancelButtonText:'取消'});else{const answer=await ElMessageBox.prompt('请输入驳回原因','驳回计量修正',{inputPattern:/\S+/,inputErrorMessage:'必须填写驳回原因',confirmButtonText:'驳回',cancelButtonText:'取消'});comment=answer.value}await enterpriseMeteringApi.reviewReadingCorrection(row.correctionId,{decision,comment,version:row.correctionVersion});await load();ElMessage.success(decision==='APPROVED'?'修正已批准并进入结算值':'修正已驳回')}catch(error){if(error!=='cancel'&&error!=='close')ElMessage.error(errorMessage(error,'审批计量修正失败'))}
}
watch([page,pageSize],()=>load());watch(()=>runtime.pageSize,value=>{pageSize.value=value});onMounted(load);
</script>

<template>
  <DsListPageShell title="计量数据质量" subtitle="原始值、修正值和结算值分层留痕；计量修正不进入平衡边界调整" page-class="enterprise-metering-page" :loading="loading">
    <div class="enterprise-content"><section class="enterprise-query-bar enterprise-query-bar--subitems"><div class="enterprise-query-bar__field enterprise-query-bar__field--date"><label>数据周期</label><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期"/></div><div class="enterprise-query-bar__field enterprise-query-bar__field--short"><label>质量状态</label><el-select v-model="status" placeholder="全部质量状态" clearable><el-option label="正常" value="GOOD"/><el-option label="已修正" value="CORRECTED"/><el-option label="估算" value="ESTIMATED"/><el-option label="可疑" value="SUSPECT"/><el-option label="缺失" value="MISSING"/></el-select></div><div class="enterprise-query-bar__actions"><el-button type="primary" :icon="Search" @click="load(true)">查询</el-button><el-button :icon="Refresh" @click="load()">刷新</el-button></div></section><section class="enterprise-kpis"><article><span>正常数据</span><strong>{{ result.goodCount }}</strong><small>无需修正</small></article><article><span>已批准修正</span><strong>{{ result.correctedCount }}</strong><small>原始值与修正值均保留</small></article><article><span>估算数据</span><strong class="enterprise-warning">{{ result.estimatedCount }}</strong><small>必须具有依据与来源</small></article><article><span>质量问题</span><strong :class="{'enterprise-danger':result.issueCount}">{{ result.issueCount }}</strong><small>包含缺失、可疑、估算和修正</small></article></section>
      <section class="enterprise-panel enterprise-table-shell"><header class="enterprise-panel__header"><div><h2>区间电量与修正审计</h2><p>任何已参与历史核算的记录只能追加修订，不能原地覆盖；修正发起与审批执行职责分离。</p></div></header><section class="ds-list-table-shell ds-list-table-shell--embedded"><DsDataTable :rows="result.rows as unknown as Record<string,unknown>[]" :columns="[]" table-layout="fixed"><el-table-column label="计量点" min-width="210"><template #default="{row}"><div class="enterprise-primary-cell"><strong>{{ row.pointName }}</strong><small>{{ row.pointCode }} · {{ row.meterName||'未绑定电表' }}</small></div></template></el-table-column><el-table-column label="数据区间" width="170"><template #default="{row}"><div class="enterprise-primary-cell"><strong>{{ row.intervalStart?.replace('T',' ').slice(0,16)||'无数据' }}</strong><small>至 {{ row.intervalEnd?.replace('T',' ').slice(0,16)||'--' }}</small></div></template></el-table-column><el-table-column label="原始 / 修正 / 结算" min-width="210" align="right"><template #default="{row}"><div class="enterprise-primary-cell"><strong>{{ format(row.rawQuantity) }} / {{ format(row.correctedQuantity) }} / {{ format(row.settlementQuantity) }}</strong><small>{{ row.unitSymbol }}</small></div></template></el-table-column><el-table-column label="修正类型" width="125"><template #default="{row}">{{ enumLabel('correctionType',row.correctionType) }}</template></el-table-column><el-table-column label="数据来源" width="120"><template #default="{row}"><DsTag type="info">{{ enumLabel('meteringSourceType',row.sourceType) }}</DsTag></template></el-table-column><el-table-column label="质量状态" width="100"><template #default="{row}"><DsTag :type="tone(row.qualityStatus)">{{ enumLabel('qualityStatus',row.qualityStatus) }}</DsTag></template></el-table-column><el-table-column prop="evidenceReference" label="校验证据" min-width="180" show-overflow-tooltip/><el-table-column v-if="canShowCorrect||canShowApprove" label="操作" width="150" fixed="right"><template #default="{row}"><div class="ds-row-actions"><template v-if="row.correctionStatus==='PENDING'"><DsTag v-if="row.correctionRequestedBy===auth.account?.id" type="info">待他人审批</DsTag><template v-else-if="canShowApprove"><el-button v-permission="'platform:enterprise-metering:quality:approve'" link type="success" :disabled="!canApprove" @click="reviewCorrection(row,'APPROVED')">批准</el-button><el-button v-permission="'platform:enterprise-metering:quality:approve'" link type="danger" :disabled="!canApprove" @click="reviewCorrection(row,'REJECTED')">驳回</el-button></template></template><el-button v-else-if="canShowCorrect" v-permission.preview="'platform:enterprise-metering:quality:correct'" link type="primary" :icon="Edit" @click="openCorrection(row)">发起修正</el-button><span v-else>--</span></div></template></el-table-column><template #empty><DsEmpty description="当前条件暂无计量区间数据"/></template></DsDataTable><footer class="ds-list-table-footer ds-list-table-footer--pagination-only"><DsPagination v-model:page="page" v-model:page-size="pageSize" :total="result.total"/></footer></section></section>
    </div>

    <el-dialog v-model="dialogVisible" title="发起计量数据修正" width="640px" destroy-on-close><el-alert type="info" :closable="false" title="审批前不改变结算值；审批后保留原始值，并追加修正审计链。"/><el-form label-position="top" class="correction-form"><el-form-item label="计量点"><el-input :model-value="activeRow?.pointName" disabled/></el-form-item><el-form-item label="当前修正值"><el-input :model-value="`${format(activeRow?.correctedQuantity||0)} ${activeRow?.unitSymbol||'kWh'}`" disabled/></el-form-item><el-form-item label="修正类型" required><el-select v-model="correctionForm.correctionType" style="width:100%"><el-option v-for="(label,value) in correctionLabel" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item label="修正后电量" required><el-input-number v-model="correctionForm.afterQuantity" :min="0" :precision="6" :step="10"/></el-form-item><el-form-item label="证据编号/地址" required><el-input v-model="correctionForm.evidenceReference" maxlength="255"/></el-form-item><el-form-item label="修正原因" required><el-input v-model="correctionForm.reason" type="textarea" :rows="3" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="dialogVisible=false">取消</el-button><el-button v-permission="'platform:enterprise-metering:quality:correct'" type="primary" :loading="saving" :disabled="!canCorrect" @click="saveCorrection">提交审批</el-button></template></el-dialog>
  </DsListPageShell>
</template>

<style scoped>
.correction-form{display:grid;grid-template-columns:1fr 1fr;gap:0 16px;margin-top:16px}.correction-form :deep(.el-form-item:last-child){grid-column:1/-1}
@media(max-width:900px){.correction-form{grid-template-columns:1fr}.correction-form :deep(.el-form-item){grid-column:1}}
</style>
